-- ============================================
-- PANEL PRICING DATABASE — TEST DATASET
-- Material Type 10 Only
-- ============================================
-- Total records: 3168
--
-- FIELD DEFINITIONS:
--   material      : 'material type 10'
--   finish        : 'unfinished' only (no finished option for this material)
--   product_type  : 'slab' | 'shelf'
--   hardware      : 'yes' | 'no'  (shelf with/without mounting hardware)
--   thickness     : '1.75"' | '2"' | '2.1-4"' | '4.1-6"'
--   depth         : '3-6' | '6.1-12' | '12.1-16' | '16.1-20' | '20.1-24' | '24.1-28'
--   width_inches  : integer 9 through 96
--   price         : decimal price in USD
--
-- AVAILABILITY RULES FOR THIS MATERIAL:
--   Finish        : Unfinished only — no finished option
--   Shelf with hardware:
--     Available for depths: 3-6, 6.1-12, 12.1-16 (heights up to 16")
--     NOT available for depths: 16.1-20, 20.1-24, 24.1-28
--     Available for ALL widths 9"-96" within eligible depths
--
-- PLACEHOLDER PRICING:
--   Four new slab thickness options are included with placeholder prices:
--   0.5", 0.75", 1", 1.5"
--   These are marked with placeholder = 'yes' and price = 1967.00
--   When real prices are available, replace by importing an updated CSV.
--   These options should be hidden or marked 'coming soon' in the UI
--   until placeholder = 'no' for those thickness values.
--
-- PRICE LOOKUP QUERY:
--   SELECT price FROM slab_pricing
--   WHERE material = ?
--     AND finish = ?
--     AND product_type = ?
--     AND hardware = ?
--     AND thickness = ?
--     AND depth = ?
--     AND width_inches = ?
--   LIMIT 1;
--
-- ============================================
-- CONFIGURATOR UI — DIMENSION INPUT RULES
-- ============================================
--
-- ORDER FORM:
--   A single unified order form section is embedded across all product pages.
--   The form defaults to the material type of the currently displayed page.
--   All 10 material types are selectable from within the form.
--
-- WIDTH INPUT:
--   Two coordinated dropdowns:
--     Primary:   whole inches, 9 to 96
--     Secondary: fractional inches in 1/16th inch increments (1/16 through 15/16)
--   Fraction rule: if any fraction is selected, round UP to the next whole inch for pricing.
--     Example: 30 and 1/8" → looks up price for width 31"
--   Ceiling rule: if primary selection is 96" (maximum), the fraction dropdown
--     must be disabled — no fraction is permitted at the maximum width.
--
-- DEPTH INPUT:
--   Dropdown with the 6 pricing ranges:
--     3-6  |  6.1-12  |  12.1-16  |  16.1-20  |  20.1-24  |  24.1-28
--   Customer selects the range that contains their measurement.
--   Two coordinated dropdowns (whole + 1/16th fractions) within each range.
--   Fraction rule: if any fraction is selected, round UP to next whole inch,
--     then map to the appropriate pricing range.
--     Example: 6 and 1/16" rounds up to 7", maps to 6.1-12 range.
--   Ceiling rule: 28" is the maximum depth. If 28" is selected as the whole
--     inch value, the fraction dropdown must be disabled.
--
-- THICKNESS INPUT:
--   Four options presented as selectable choices:
--     1.75"   → fixed value, no fraction input needed, always prices as 1.75"
--     2"      → fixed value, no fraction input needed, always prices as 2"
--     2.1-4"  → range: customer picks any value within this range in 1/16th increments.
--               All values in this range price identically as "2.1-4"
--               Secondary dimension input shown for order record purposes only.
--               Ceiling rule: if 4" is selected, fraction dropdown must be disabled.
--     4.1-6"  → range: customer picks any value within this range in 1/16th increments.
--               All values in this range price identically as "4.1-6"
--               Secondary dimension input shown for order record purposes only.
--               Ceiling rule: if 6" is selected, fraction dropdown must be disabled.
--
-- GENERAL FRACTION / ROUNDING RULE:
--   Any fraction present on any dimension → round UP to next whole unit for pricing.
--   Fractions are recorded on the order for manufacturing purposes but do not
--   affect which price is looked up beyond the round-up rule above.
--
-- CEILING VALIDATION SUMMARY:
--   Width 96"        → fraction dropdown disabled
--   Depth 28"        → fraction dropdown disabled
--   Thickness 4"     → fraction dropdown disabled (within 2.1-4" range)
--   Thickness 6"     → fraction dropdown disabled (within 4.1-6" range)
-- ============================================

CREATE TABLE IF NOT EXISTS slab_pricing (
    id            INT AUTO_INCREMENT PRIMARY KEY,
    material      VARCHAR(20)    NOT NULL,
    finish        VARCHAR(12)    NOT NULL,
    product_type  VARCHAR(8)     NOT NULL,
    hardware      VARCHAR(3)     NOT NULL,
    thickness     VARCHAR(8)     NOT NULL,
    depth         VARCHAR(10)    NOT NULL,
    width_inches  TINYINT        NOT NULL,
    price         DECIMAL(10,2)  NOT NULL,
    placeholder   CHAR(3)        NOT NULL DEFAULT 'no',  -- 'yes' = placeholder price ($1967), real price not yet set
    INDEX idx_lookup (material, finish, product_type, hardware, thickness, depth, width_inches)
);

